def run(cmd,cwd=None,env=None,check=True,capture=False):
    print("+"," ".join(map(str,cmd)),flush=True)
    return subprocess.run(
        list(map(str,cmd)),cwd=cwd,env=env,check=check,text=True,
        capture_output=capture,
    )

def setup_conda():
    conda=MINICONDA/"bin/conda"
    if conda.exists():
        return conda
    installer=TMP/"miniforge.sh"
    urllib.request.urlretrieve(
        "https://github.com/conda-forge/miniforge/releases/latest/download/Miniforge3-Linux-x86_64.sh",
        installer,
    )
    run(["bash",str(installer),"-b","-p",str(MINICONDA)])
    return conda

def locate_driver_dirs():
    candidates=[]
    for raw in os.environ.get("LD_LIBRARY_PATH","").split(":"):
        if not raw:
            continue
        p=Path(raw)
        if p.exists() and any((p/n).exists() for n in ("libcuda.so.1","libcuda.so")):
            candidates.append(str(p))
    probe=subprocess.run(
        ["bash","-lc",
         "ldconfig -p 2>/dev/null | "
         "grep -E 'libcuda\\.so\\.1|libnvidia-ptxjitcompiler\\.so\\.1|libnvidia-nvvm\\.so' || true"],
        capture_output=True,text=True,check=False,
    )
    print("Driver probe:\n"+probe.stdout,flush=True)
    for line in probe.stdout.splitlines():
        if "=>" in line:
            p=Path(line.split("=>",1)[1].strip()).parent
            if p.exists():
                candidates.append(str(p))
    for fallback in ("/usr/local/nvidia/lib64","/usr/local/nvidia/lib","/usr/lib/x86_64-linux-gnu"):
        p=Path(fallback)
        if p.exists() and any((p/n).exists() for n in ("libcuda.so.1","libcuda.so")):
            candidates.append(str(p))
    out=[]
    for p in candidates:
        if p not in out:
            out.append(p)
    if not out:
        raise RuntimeError("Could not locate Kaggle NVIDIA driver libraries")
    return out,probe.stdout

def setup_odin(conda):
    env=os.environ.copy()
    env["PATH"]=f"{MINICONDA}/bin:"+env.get("PATH","")
    env.pop("PYTHONPATH", None)
    env.pop("PYTHONHOME", None)
    if not ODIN.exists():
        run([
            "git","clone","--recurse-submodules","--depth","1",
            "https://github.com/DigBioLab/odin_multi.git",str(ODIN)
        ],env=env)
    marker=MINICONDA/"envs/Odin-Multi/bin/python"
    channels = run(
        [str(MINICONDA/"bin/conda"), "config", "--show", "channels"],
        env=env, capture=True, check=False,
    )
    (OUT/"conda_channels.txt").write_text(
        (channels.stdout or "") + (channels.stderr or ""),
        encoding="utf-8",
    )
    print("Conda channels:\n" + (channels.stdout or ""), flush=True)
    if not marker.exists():
        run([
            "bash","install_odin_multi.sh",
            "--cuda","12.4",
            "--pkg-manager","conda",
        ],cwd=ODIN,env=env)
    else:
        print("Odin-Multi conda environment already present.",flush=True)
    return env

EXPECTED_TARGET_RESIDUES={
    "human_tfr1_apical_189_383.pdb":(189,383,195),
    "mouse_tfr1_apical_homolog.pdb":(191,385,194),
}


def _ca_residues(path):
    nums=[]
    for line in path.read_text(errors="replace").splitlines():
        if line.startswith("ATOM") and len(line)>=54 and line[12:16].strip()=="CA":
            try:
                nums.append(int(line[22:26]))
            except ValueError:
                continue
    return nums


def _ca_residues_by_chain(path):
    out={}
    for line in path.read_text(errors="replace").splitlines():
        if line.startswith("ATOM") and len(line)>=54 and line[12:16].strip()=="CA":
            chain=line[21].strip() or "_"
            try:
                resid=int(line[22:26])
            except ValueError:
                continue
            out.setdefault(chain,[]).append(resid)
    return out


def materialize_targets():
    """Write the embedded target PDBs to disk and fail fast if anything is wrong.

    This MUST run before the ~12 minute conda/Odin-Multi installation so that a
    packaging regression costs seconds instead of a whole GPU session. The
    2026-10-29 smoke failed only after the full install because the inputs were
    never uploaded by `kaggle kernels push` (script kernels ship `code_file` only).
    """
    print("=== Stage 0: verifying embedded target inputs ===",flush=True)
    missing=[n for n in EXPECTED_TARGET_RESIDUES if n not in EMBEDDED_TARGET_GZ_B64]
    if missing:
        raise SystemExit(
            "FATAL: embedded target payload missing for "+", ".join(sorted(missing))
            +". Run `python scripts/embed_odin_multi_targets.py` and re-push."
        )

    paths={}
    for name,(lo,hi,expected_ca) in EXPECTED_TARGET_RESIDUES.items():
        dest=OUT/name
        try:
            raw=gzip.decompress(base64.b64decode(EMBEDDED_TARGET_GZ_B64[name]))
        except Exception as exc:
            raise SystemExit(f"FATAL: cannot decode embedded payload for {name}: {exc}")

        digest=hashlib.sha256(raw).hexdigest()
        expected=EMBEDDED_TARGET_SHA256.get(name)
        if digest!=expected:
            raise SystemExit(
                f"FATAL: sha256 mismatch for {name}: got {digest}, expected {expected}. "
                "The embedded payload is out of sync with the repository PDB."
            )

        dest.write_bytes(raw)
        nums=_ca_residues(dest)
        if not nums:
            raise SystemExit(f"FATAL: no CA atoms parsed from {name}.")
        if min(nums)!=lo or max(nums)!=hi or len(nums)!=expected_ca:
            raise SystemExit(
                f"FATAL: {name} residue numbering is wrong: CA range "
                f"{min(nums)}-{max(nums)} count {len(nums)}, expected {lo}-{hi} count {expected_ca}. "
                "Hotspot restraints would silently miss their intended residues."
            )
        print(
            f"  OK {name}: {len(raw)} bytes, sha256={digest[:16]}..., "
            f"CA {min(nums)}-{max(nums)} (n={len(nums)}) -> {dest}",
            flush=True,
        )
        paths[name]=dest

    # The mouse model is the human apical frame renumbered +2; the hotspot pairs
    # must line up or the cross-reactivity objective is meaningless.
    human_ca=set(_ca_residues(paths["human_tfr1_apical_189_383.pdb"]))
    mouse_ca=set(_ca_residues(paths["mouse_tfr1_apical_homolog.pdb"]))
    for h,m in ((343,345),(344,346),(347,349),(350,352)):
        if h not in human_ca:
            raise SystemExit(f"FATAL: human hotspot {h} absent from target PDB.")
        if m not in mouse_ca:
            raise SystemExit(f"FATAL: mouse hotspot {m} absent from target PDB.")
    print("  OK all 4 human/mouse hotspot pairs present.",flush=True)

    for name,spec in ESCAPE_SPECS.items():
        if name not in EMBEDDED_ESCAPE_B64:
            raise SystemExit(f"FATAL: missing embedded escape decoy {name}")
        dest=OUT/name
        raw=base64.b64decode(EMBEDDED_ESCAPE_B64[name])
        dest.write_bytes(raw)
        by_chain=_ca_residues_by_chain(dest)
        for chain,(lo,hi,n) in spec.items():
            vals=by_chain.get(chain,[])
            if not vals or min(vals)!=lo or max(vals)!=hi or len(vals)!=n:
                raise SystemExit(
                    f"FATAL: {name} chain {chain} CA range/count wrong: "
                    f"{(min(vals),max(vals),len(vals)) if vals else 'missing'}, "
                    f"expected {(lo,hi,n)}"
                )
        print(
            f"  OK {name}: "
            +", ".join(
                f"{ch} {min(by_chain[ch])}-{max(by_chain[ch])} (n={len(by_chain[ch])})"
                for ch in sorted(spec)
            ),
            flush=True,
        )
        paths[name]=dest

    print("=== Stage 0 passed ===",flush=True)
    return paths



V6_WARM_START_SEQUENCE="SPSVISTTTTTYTYHGKQVTRIRTTINPGEKIEPAPGERQMRGRDWETGYIIVHTYKVNS"

def patch_odin_warm_start():
    """Warm-start the shared multi-context sequence from the validated v6 parent.

    Odin/ColabDesign evaluates auxiliary target contexts with the same params["seq"],
    so restarting the main design model with this sequence initializes every target
    context from one shared binder sequence. The patch is deliberately inserted only
    after all target contexts have been prepared and before campaign loss weights are set.
    """
    path=ODIN/"functions/colabdesign_utils.py"
    text=path.read_text()
    old='''    if aux_params_list:
        af_model.prep_offtarget_inputs(aux_params_list)

    af_model._args["gradient_weight"] = float(main_advanced["gradient_weight"])
'''
    new=f'''    if aux_params_list:
        af_model.prep_offtarget_inputs(aux_params_list)

    warm_start_seq = "SPSVISTTTTTYTYHGKQVTRIRTTINPGEKIEPAPGERQMRGRDWETGYIIVHTYKVNS"
    if len(warm_start_seq) != length:
        raise ValueError(f"Warm-start length {{len(warm_start_seq)}} != requested binder length {{length}}")
    print(f"[WARM START] shared binder initialized from FreeBindCraft v6 sequence ({{length}} aa)")
    af_model.restart(seed=seed, seq=warm_start_seq)

    af_model._args["gradient_weight"] = float(main_advanced["gradient_weight"])
'''
    if old not in text:
        raise RuntimeError("Odin warm-start insertion point not found; refusing unverified patch")
    path.write_text(text.replace(old,new,1))
    (OUT/"odin_warm_start_patch.txt").write_text(
        "Inserted af_model.restart(seed=seed, seq=V6_WARM_START_SEQUENCE) after multi-context prep.\n"
        "Shared sequence: "+V6_WARM_START_SEQUENCE+"\n"
    )
    print("Patched Odin-Multi for shared v6 sequence warm-start.",flush=True)


